+            FuncKeyKind::ArrayToWasmTrampoline | FuncKeyKind::WasmToBuiltinTrampoline => false,
+
+            #[cfg(feature = "component-model")]
+            FuncKeyKind::ComponentTrampoline | FuncKeyKind::ResourceDropTrampoline => true,
+        }
+    }
