+            (def_func_key(0, 1), Some(10)),
+            (def_func_key(0, 2), Some(20)),
+            (def_func_key(0, 3), None),
+            (def_func_key(0, 4), None),
+            (def_func_key(0, 5), Some(30)),
+            (array_to_wasm_tramp_key(0, 0), None),
+            (array_to_wasm_tramp_key(0, 1), Some(100)),
